const s = $getWorkflowStaticData('global');
const ahora = Date.now();
const H = 3600e3;
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const hoy = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Santiago' });
const lunes = new Date().toLocaleDateString('en-US', { timeZone: 'America/Santiago', weekday: 'short' }) === 'Mon';
const out = [];
const avisar = texto => out.push({ json: { texto } });

// n8n decide cuando avisar: el script reporta siempre y aqui se detectan los cambios de estado,
// para no mandar la misma alerta cada hora.
const p = $json.body || {};

if (p.tipo === 'origen') {
  if (p.prueba) {
    avisar('\u{1F9EA} <b>PRUEBA</b> del chequeo de origen (' + esc(p.host) + ')\n\n' + (p.fallos || []).map(f => '• ' + esc(f)).join('\n'));
    return out;
  }
  s.origen_visto = ahora;
  const antes = s.origen_ok;
  if (!p.ok) {
    if (antes !== false || ahora - (s.origen_alerta || 0) > 6 * H) {
      avisar('\u{1F6A8} <b>El origen de ' + esc(p.host) + ' dejo de estar protegido</b>\n\n' +
        (p.fallos || []).map(f => '• ' + esc(f)).join('\n') +
        '\n\nRevisar: Transform Rule "Autenticacion de origen" en Cloudflare, bloque "NexaSec Origen" del .htaccess, y que Cloudflare no este pausado.');
      s.origen_alerta = ahora;
    }
    s.origen_ok = false;
  } else {
    if (antes === false) avisar('✅ Origen de ' + esc(p.host) + ' protegido de nuevo: directo 403, Cloudflare 200.');
    s.origen_ok = true;
  }
  return out;
}

if (p.tipo === 'plugins') {
  const vul = (p.vulnerables || []).filter(v => !v.informativo);
  const linea = v => '• <b>' + esc(v.slug) + '</b> ' + esc(v.version) + ' (' + esc(v.tipo) + ')' + (v.severidad ? ' — ' + esc(v.severidad) + (v.cvss ? ' ' + v.cvss : '') : '') +
    '\n  ' + esc(v.titulo) +
    '\n  ' + ((v.parche || []).length ? 'Corregido en: ' + esc(v.parche.join(', ')) : 'Sin parche publicado') + (v.cve ? ' · ' + esc(v.cve) : '') +
    (v.ref ? '\n  ' + esc(v.ref) : '');

  // Vencimiento del dominio (whois de NIC Chile, desde el servidor del sitio).
  const diasDominio = p.dominio_vence ? Math.floor((new Date(p.dominio_vence) - ahora) / 86400000) : null;
  const avisoDominio = () => '\u{1F310} <b>Renovar ' + esc(p.host) + '</b>: ' +
    (diasDominio <= 0 ? '<b>VENCIO</b>' : 'vence en <b>' + diasDominio + ' dias</b>') +
    ' (' + esc(String(p.dominio_vence).slice(0, 10)) + ').\n' +
    'Si vence se pierden la web, el correo y todo lo que cuelga del dominio.\n' +
    'Renovar en https://www.nic.cl → Mis dominios. Conviene pagar varios anos de una vez.';

  if (p.prueba) {
    if (diasDominio !== null) avisar('\u{1F9EA} PRUEBA — asi se vera el aviso de renovacion:\n\n' + avisoDominio());
    avisar('\u{1F9EA} <b>PRUEBA</b> del vigia de plugins (' + esc(p.host) + ')\n\n' + vul.map(linea).join('\n\n') +
      ((p.errores || []).length ? '\n\nErrores reportados:\n' + p.errores.map(e => '• ' + esc(e)).join('\n') : ''));
    return out;
  }
  s.plugins_visto = ahora;

  if (diasDominio !== null && ([90, 60, 45, 30, 21, 14, 10, 7, 5, 3, 2, 1].includes(diasDominio) || diasDominio <= 0)) {
    avisar(avisoDominio());
  }

  const clave = v => v.id + '@' + v.version;
  const previas = new Set(s.vuln_ids || []);
  const nuevas = vul.filter(v => !previas.has(clave(v)));
  if (nuevas.length) {
    avisar('\u{1F534} <b>Vulnerabilidades nuevas en ' + esc(p.host) + '</b>\n\n' + nuevas.map(linea).join('\n\n') +
      '\n\nActualizar desde wp-admin → Plugins. Si no hay parche, evaluar desactivar el plugin.');
  } else if (vul.length && lunes && s.vuln_recordado !== hoy) {
    avisar('\u{1F7E0} <b>Siguen sin parchear</b> en ' + esc(p.host) + '\n\n' + vul.map(linea).join('\n\n'));
    s.vuln_recordado = hoy;
  }
  if (!vul.length && previas.size) avisar('✅ Ya no quedan vulnerabilidades conocidas en ' + esc(p.host) + '.');
  s.vuln_ids = vul.map(clave);

  if ((p.errores || []).length && s.plugins_error_dia !== hoy) {
    avisar('⚠️ <b>Vigia de plugins con problemas</b>\n' + p.errores.map(e => '• ' + esc(e)).join('\n'));
    s.plugins_error_dia = hoy;
  }

  if (lunes && s.inventario_dia !== hoy && p.feed_registros) {
    const pend = [...(p.plugins || []), ...(p.temas || [])].filter(x => x.actualizacion);
    avisar('\u{1F4CB} <b>Inventario semanal de ' + esc(p.host) + '</b>\n' +
      'WordPress ' + esc(p.core) + ' · ' + (p.plugins || []).length + ' plugins · ' + (p.temas || []).length + ' temas\n' +
      'Vulnerabilidades conocidas: ' + vul.length + ' (feed Wordfence: ' + p.feed_registros + ' registros)\n' +
      (diasDominio !== null ? 'Dominio vence en ' + diasDominio + ' dias (' + esc(String(p.dominio_vence).slice(0, 10)) + ')\n' : '') +
      (pend.length ? 'Actualizaciones disponibles: ' + pend.map(x => esc(x.slug) + ' ' + esc(x.version) + '→' + esc(x.actualizacion)).join(', ') + '\n' : '') +
      ((p.sin_cobertura || []).length ? '\nSin registros en el feed (nunca tuvieron fallos publicados, o son premium y hay que vigilarlos a mano):\n' + p.sin_cobertura.map(x => '• ' + esc(x)).join('\n') : ''));
    s.inventario_dia = hoy;
  }
  return out;
}

avisar('⚠️ Vigia recibio un payload desconocido: ' + esc(JSON.stringify(p).slice(0, 200)));
return out;

const s = $getWorkflowStaticData('global');
const ahora = Date.now();
const H = 3600e3;
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const hoy = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Santiago' });
const lunes = new Date().toLocaleDateString('en-US', { timeZone: 'America/Santiago', weekday: 'short' }) === 'Mon';
const out = [];
const avisar = texto => out.push({ json: { texto } });

// Un sensor que deja de reportar se ve igual que uno que no encuentra nada. Esto los distingue.
const chequeos = [
  ['origen_visto', 3, 'el chequeo de origen (cron horario en el servidor)'],
  ['plugins_visto', 26, 'el inventario de plugins (cron diario en el servidor)'],
];
for (const [clave, limite, nombre] of chequeos) {
  const visto = s[clave];
  if (!visto || ahora - visto <= limite * H) continue;
  if (ahora - (s[clave + '_alerta'] || 0) < 12 * H) continue;
  const horas = Math.round((ahora - visto) / H);
  avisar('⏰ <b>Vigia sin reportar</b>: ' + nombre + ' no llega hace ' + horas + ' h.\nRevisar crontab y ~/nx-kit/vigia.log en el hosting.');
  s[clave + '_alerta'] = ahora;
}
return out;
